#!/usr/bin/env python3
import sys
import os

# 1. Headers output
# It is vital to print the header followed by a blank line.
# Your splitOutput() method looks for "\r\n\r\n" or "\n\n" to separate this from the body.
print("Content-Type: text/html")
print("Status: 200 OK")
print() # Prints the empty line break that delimits the headers

# 2. Body output
print("<!DOCTYPE html>")
print("<html>")
print("<head><title>Prueba CGI</title></head>")
print("<body>")
print("<h1>CGI Ejecutado Correctamente</h1>")

# Read environment variables generated by your buildEnv() method
method = os.environ.get("REQUEST_METHOD", "Desconocido")
print("<h3>Información de la Petición</h3>")
print("<ul>")
print("<li><strong>Método:</strong> " + method + "</li>")
print("<li><strong>URI:</strong> " + os.environ.get("SCRIPT_NAME", "N/A") + "</li>")
print("<li><strong>Query String:</strong> " + os.environ.get("QUERY_STRING", "N/A") + "</li>")
print("</ul>")

# 3. Read STDIN if it is a POST (what your server sends with writeToCgi)
if method == "POST":
    try:
        content_length = int(os.environ.get("CONTENT_LENGTH", "0"))
    except ValueError:
        content_length = 0

    if content_length > 0:
        # Reads exactly the bytes indicated by Content-Length from the input pipe
        body = sys.stdin.read(content_length)
        print("<h3>Body Recibido (vía Pipe STDIN):</h3>")
        print("<pre>" + body + "</pre>")
    else:
        print("<p>Petición POST recibida sin Content-Length o con tamaño 0.</p>")

print("</body>")
print("</html>")